using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing {
public sealed class HighwayPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> checks=new List<string>();bool failed;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--highway-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=folder+"/isolated-profile.json";TrafficWorld.DisabledForTests=true;}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder!=null){var g=new GameObject("Isolated highway native verification");DontDestroyOnLoad(g);g.AddComponent<HighwayPlayerProbe>();}}
 void Check(bool ok,string s){checks.Add((ok?"PASS ":"FAIL ")+s);File.WriteAllLines(folder+"/results.txt",checks);if(!ok){failed=true;Application.Quit(1);throw new Exception(s);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string t,string trace,LogType type){if(!failed&&(type==LogType.Error||type==LogType.Exception))Check(false,"Runtime error: "+t);}
 IEnumerator Shot(string name){yield return new WaitForEndOfFrame();var c=Camera.main;var target=c.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(1280,720,24,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear){antiAliasing=4};rt.Create();c.targetTexture=rt;c.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false,true);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();var pixels=image.GetPixels();for(int i=0;i<pixels.Length;i++)pixels[i]=pixels[i].gamma;image.SetPixels(pixels);image.Apply();File.WriteAllBytes(folder+"/"+name+".png",image.EncodeToPNG());c.targetTexture=target;RenderTexture.active=active;rt.Release();Destroy(rt);Destroy(image);yield return new WaitForSecondsRealtime(.4f);}
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=90;Check(HighwayRuntime.Instance==null,"Hub has no highway instance");yield return SceneManager.LoadSceneAsync("HarborVale_CityMap");FinchVehicle car=null;float deadline=Time.realtimeSinceStartup+30;while(car==null&&Time.realtimeSinceStartup<deadline){car=FindAnyObjectByType<DocksideTrialDirector>()?.vehicle;yield return null;}Check(car!=null,"City launches with actual player vehicle");Check(FindObjectsByType<HighwayRuntime>(FindObjectsSortMode.None).Length==1,"City installs exactly one highway");HighwayRuntime.Hook();Check(FindObjectsByType<HighwayRuntime>(FindObjectsSortMode.None).Length==1,"Repeated highway hook does not duplicate geometry");var network=HighwayNetwork.Load();var middle=network.Carriageway(false)[300];Vector3 p;Quaternion q;Check(HighwayRuntime.TryRecovery(middle+Vector3.up,Vector3.right,out p,out q)&&Mathf.Abs(p.y-middle.y)<1,"Recovery recognizes elevated highway");Check(!HighwayRuntime.TryRecovery(new Vector3(middle.x,HighwayNetwork.GroundHeight(middle.z),middle.z),Vector3.right,out p,out q),"Recovery does not pull a street-level car onto the overpass");
 var path=new List<Vector3>();var road=network.cityRoads.First(r=>r.id=="RD08");for(int i=Math.Max(0,road.points.Length-20);i<road.points.Length;i++)path.Add(HighwayNetwork.Offset(road.points,i,1.8f,false));foreach(var r in network.ramps.Take(2))for(int i=0;i<r.points.Length;i++){var point=HighwayNetwork.Offset(r.points,i,r.lanes==2?1.8f:0,false);if(path.Count==0||Vector3.Distance(path.Last(),point)>.3f)path.Add(point);}int merge=path.Count;var main=network.center.Select((v,i)=>HighwayNetwork.Offset(network.center,i,10.2f,true)).ToArray();int nearest=Enumerable.Range(0,main.Length).OrderBy(i=>(main[i]-path.Last()).sqrMagnitude).First();for(int i=1;i<180;i++)path.Add(main[(nearest+i)%main.Length]);
 var pilot=car.gameObject.AddComponent<RoadPilot>();pilot.Car=car;pilot.Path=path.ToArray();pilot.Lane=0;pilot.IsRival=true;pilot.CruiseKph=35;car.externalInput=true;car.controlsLocked=false;pilot.Place(2);var camera=Camera.main.GetComponent<FinchChaseCamera>();camera.Snap();yield return Shot("City_highway_access");Time.timeScale=4;float peak=0;int air=0;deadline=Time.realtimeSinceStartup+120;bool captured=false;while(pilot.Index<path.Count-6&&Time.realtimeSinceStartup<deadline){if(pilot.Index>=merge+10)pilot.CruiseKph=95;peak=Mathf.Max(peak,car.SpeedKph);if(car.GroundedWheels==0&&pilot.DistanceMoved>10)air++;if(!captured&&pilot.Index>merge+30){captured=true;yield return Shot("Driving_expressway");}CheckUpright(car);yield return new WaitForFixedUpdate();}Time.timeScale=1;Check(pilot.Index>=path.Count-6,"Player car drives original city street, access ramp and highway: distance="+pilot.DistanceMoved.ToString("F0")+"m, peak="+peak.ToString("F1")+"km/h, airborneTicks="+air);Check(pilot.Recoveries==0,"Highway route needs no recovery resets");Destroy(pilot);car.commandedPedal=0;car.commandedServiceBrake=1;car.Recover();Check(car.transform.position.y>100,"Normal vehicle Recover stays on elevated highway");yield return Shot("Highway_recovery");yield return SceneManager.LoadSceneAsync("HarborVale_Hub");Check(HighwayRuntime.Instance==null,"Leaving city unloads highway");yield return SceneManager.LoadSceneAsync("HarborVale_CityMap");Check(FindObjectsByType<HighwayRuntime>(FindObjectsSortMode.None).Length==1,"Returning to city restores one highway");Check(!failed,"Highway native flow has no runtime errors");Application.Quit(0);}
 void CheckUpright(FinchVehicle car){if(Vector3.Dot(car.transform.up,Vector3.up)<.65f)Check(false,"Player car tipped during highway route");}
}
}
